function p=v4DefaultBParameters()
% Project-structure defaults expressed in SF12 units; calibration must freeze.
p=struct('searchStepBins',0.05,'residualSearchBins',(-1:0.05:1).', ...
    'historyDecay',0.85,'huberThresholdBins',0.30, ...
    'residualPeakRatioThreshold',1.05,'decisionPeakRatioThreshold',1.20, ...
    'innovationLimitBins',0.75,'singleSymbolInnovationGain',0.35, ...
    'phasePairInnovationGain',0.60,'phasePairInnovationLimitBins',0.25, ...
    'phasePairAgreementLimitBins',0.30,'virtualPilotCfoStdBins',0.10, ...
    'virtualPilotRateStdLimitBinsPerSec',1.0,'rateDeviationLimitBinsPerSec',4.0, ...
    'maximumRateBinsPerSec',20,'confidenceAlpha',0.8,'confidenceMix',0.5, ...
    'confidenceThresholdScale',1.0,'softHammingMarginRatio',0.15, ...
    'minimumCrossFrameHistoryForVirtualPilots',1);
p.requireSoftHardAgreement=true;
end
